<?php
namespace ServSys\ServiceCalls;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class CompletionCodeService {
 private $codes; private $relations; private $calls;
 public function __construct(CompletionCodeRepository $codes=null,ServiceCallCompletionRepository $relations=null,ServiceCallRepository $calls=null){$this->codes=$codes?:new CompletionCodeRepository();$this->relations=$relations?:new ServiceCallCompletionRepository();$this->calls=$calls?:new ServiceCallRepository();}
 public function save(array $input,int $id=0): int {$description=sanitize_text_field($input['description']??'');if(''===$description){throw new \InvalidArgumentException('Completion Code description is required.');}$data=array('description'=>$description,'sort_order'=>(int)($input['sort_order']??0),'active'=>empty($input['active'])?0:1,'updated_at'=>current_time('mysql',true),'updated_by'=>get_current_user_id()?:null);if($id){if(!$this->codes->find($id)){throw new \InvalidArgumentException('Completion Code does not belong to the current company.');}if(!$this->codes->update($id,$data)){throw new \RuntimeException('Unable to update Completion Code.');}return $id;}$data['created_at']=$data['updated_at'];$data['created_by']=$data['updated_by'];$id=$this->codes->create($data);if(!$id){throw new \RuntimeException('Unable to create Completion Code.');}return $id;}
 public function assign(int $service_call_id,int $completion_code_id): int {$call=$this->calls->find($service_call_id);if(!$call){throw new \InvalidArgumentException('Service Call does not belong to the current company.');}$code=$this->codes->find($completion_code_id);if(!$code){throw new \InvalidArgumentException('Completion Code does not belong to this Service Call company.');}if(empty($code['active'])){throw new \InvalidArgumentException('Inactive Completion Codes cannot be newly assigned.');}if($this->relations->exists($service_call_id,$completion_code_id)){return 0;}$id=$this->relations->add($service_call_id,$completion_code_id);if(!$id){throw new \RuntimeException('Unable to assign Completion Code.');}return $id;}
 public function unassign(int $service_call_id,int $completion_code_id): void {if(!$this->calls->find($service_call_id)){throw new \InvalidArgumentException('Service Call does not belong to the current company.');}$code=$this->codes->find($completion_code_id);if(!$code){throw new \InvalidArgumentException('Completion Code does not belong to this Service Call company.');}$this->relations->remove($service_call_id,$completion_code_id);}
}
